import{_ as o,r as s,o as p,c as l,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Поле Entries - October CMS - 3.x","titleTemplate":false,"description":"Контентное поле","frontmatter":{"subtitle":"Контентное поле","shortname":"Entries"},"headers":[{"level":2,"title":"Применение условий","slug":"применение-условии","link":"#применение-условии","children":[{"level":3,"title":"SQL-условие запроса","slug":"sql-условие-запроса","link":"#sql-условие-запроса","children":[]},{"level":3,"title":"PHP-области запроса","slug":"php-области-запроса","link":"#php-области-запроса","children":[]}]},{"level":2,"title":"Определение обратного отношения","slug":"определение-обратного-отношения","link":"#определение-обратного-отношения","children":[]},{"level":2,"title":"Отображение в столбце списка","slug":"отображение-в-столбце-списка","link":"#отображение-в-столбце-списка","children":[{"level":3,"title":"Отображение как счётчик","slug":"отображение-как-счетчик","link":"#отображение-как-счетчик","children":[]}]},{"level":2,"title":"Расширенное управление записями","slug":"расширенное-управление-записями","link":"#расширенное-управление-записями","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/element/content/field-entries.md","filePath":"3.x/ru/element/content/field-entries.md"}'),u={name:"3.x/ru/element/content/field-entries.md"};function i(d,a,k,g,y,h){const e=s("pre-heading"),t=s("post-heading");return p(),l("div",null,[n(e),a[0]||(a[0]=c("h1",null,"Поле Entries",-1)),n(t),a[1]||(a[1]=r(`<p><code>entries</code> — связывает с другими записями по UUID или handle.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Author
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> &lt;uuid<span class="token punctuation">|</span>handle<span class="token punctuation">&gt;</span>
</code></pre></div><p>Поддерживаются следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>source</strong></td><td>UUID или handle связанного блюпринта.</td></tr><tr><td><strong>maxItems</strong></td><td>ограничивает количество записей, которые можно выбрать.</td></tr><tr><td><strong>displayMode</strong></td><td>изменяет способ отображения поля. Поддерживаемые значения: <code>relation</code>, <code>recordfinder</code>, <code>taglist</code>, <code>controller</code>. По умолчанию: <code>relation</code>.</td></tr><tr><td><strong>conditions</strong></td><td>задаёт необработанное условие where для применения к запросу модели.</td></tr><tr><td><strong>modelScope</strong></td><td>применяет метод <a href="./../../extend/database/model.html">области запроса модели</a> к <strong>связанной модели формы</strong>, может быть именем метода модели или статическим методом PHP-класса (<code>Class::method</code>).</td></tr><tr><td><strong>inverse</strong></td><td>при определении как обратное отношение — имя связанного поля в исходном блюпринте.</td></tr></tbody></table></div><p>Для ограничения количества выбираемых элементов используйте свойство <code>maxItems</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">1</span>
</code></pre></div><p>Для отображения record finder вместо стандартного элемента управления используйте свойство <code>displayMode</code>. Этот режим доступен только когда выбирается один элемент.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> recordfinder
</code></pre></div><p>Когда доступно несколько элементов, <code>displayMode</code> поддерживает выбор элементов с помощью списка тегов.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> taglist
</code></pre></div><h2 id="применение-условии"><a href="#применение-условии" class="header-anchor">#</a> Применение условий</h2><p>Вы можете ограничить связанный запрос с помощью SQL или PHP, используя подходы ниже. В примерах связанная запись имеет поле <code>is_featured</code>, которое рендерится как чекбокс. Мы можем ограничить связанные записи только теми, у которых этот чекбокс отмечен.</p><h3 id="sql-условие-запроса"><a href="#sql-условие-запроса" class="header-anchor">#</a> SQL-условие запроса</h3><p>Вы можете ограничить связанную модель с помощью необработанного SQL-запроса, используя свойство <code>conditions</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">categories</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Categories
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Blog\\Category
    <span class="token key atrule">conditions</span><span class="token punctuation">:</span> is_featured = true
</code></pre></div><h3 id="php-области-запроса"><a href="#php-области-запроса" class="header-anchor">#</a> PHP-области запроса</h3><p>Вы можете ограничить связанный запрос с помощью PHP-метода, используя свойство <code>scope</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">basic_entries</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Basic Entry
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Basic\\Entry
    <span class="token key atrule">scope</span><span class="token punctuation">:</span> App\\Classes\\ScopeHelper<span class="token punctuation">:</span><span class="token punctuation">:</span>applyScope
</code></pre></div><p>Это будет ссылаться на класс <code>App\\Classes\\ScopeHelper</code>, который может быть файлом, расположенным в <strong>app/classes/ScopeHelper.php</strong>, например.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">App<span class="token punctuation">\\</span>Classes</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">ScopeHelper</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">function</span> <span class="token function-definition function">applyScope</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_featured&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="определение-обратного-отношения"><a href="#определение-обратного-отношения" class="header-anchor">#</a> Определение обратного отношения</h2><p>В некоторых случаях вы можете захотеть получить доступ к отношению в обратном направлении, например, найти все записи, принадлежащие определённой категории. Свойство <code>inverse</code> может использоваться для связывания отношения в противоположном направлении, где значение свойства устанавливается в имя поля в исходном блюпринте.</p><p>Например, если блюпринт <strong>Blog\\Post</strong> уже имеет определённое отношение <code>categories</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">categories</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Blog\\Category
</code></pre></div><p>Блюпринт <strong>Blog\\Category</strong> может включать поле <code>posts</code> как <code>inverse</code> поля <code>categories</code>, найденного в исходном блюпринте (выше). Поле может быть исключено из форм, установив значение <code>hidden</code> в <code>true</code>, и это необязательно.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">posts</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Blog\\Post
    <span class="token key atrule">inverse</span><span class="token punctuation">:</span> categories
    <span class="token key atrule">hidden</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h2 id="отображение-в-столбце-списка"><a href="#отображение-в-столбце-списка" class="header-anchor">#</a> Отображение в столбце списка</h2><p>По умолчанию поле entries отображается как гиперссылка на связанную запись.</p><h3 id="отображение-как-счетчик"><a href="#отображение-как-счетчик" class="header-anchor">#</a> Отображение как счётчик</h3><p>Для отображения столбца списка со счётчиком связанных записей вы можете использовать следующую <a href="./../list-columns.html">конфигурацию столбца</a>. Свойство <code>relation</code> должно быть установлено в имя поля, с <code>relationCount</code> установленным в <code>true</code> и типом столбца <code>number</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">categories</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Categories
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token comment"># ...</span>
    <span class="token key atrule">column</span><span class="token punctuation">:</span>
        <span class="token key atrule">relation</span><span class="token punctuation">:</span> categories
        <span class="token key atrule">relationCount</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> number
</code></pre></div><h2 id="расширенное-управление-записями"><a href="#расширенное-управление-записями" class="header-anchor">#</a> Расширенное управление записями</h2><p>Для создания, обновления и удаления элементов внутри формы установите <code>displayMode</code> в controller для отображения расширенного режима управления, работающего на основе <a href="./../../extend/forms/relation-controller.html">поведения Relation Controller</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> controller
</code></pre></div><p>Если блюпринт имеет <code>navigation</code> установленный в <code>false</code>, то кнопки по умолчанию будут показывать <strong>Create</strong> и <strong>Delete</strong>. Если навигация определена, то кнопки показывают <strong>Add</strong> и <strong>Remove</strong>. Вы можете настроить кнопки с помощью свойства <code>toolbarButtons</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> create<span class="token punctuation">|</span>add<span class="token punctuation">|</span>remove<span class="token punctuation">|</span>delete
</code></pre></div><p>Различные сообщения, используемые в relation controller, берутся из свойства <code>customMessages</code> исходного блюпринта, и вы также можете изменить их с помощью <code>customMessages</code> в определении поля.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">author</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
        <span class="token key atrule">buttonCreate</span><span class="token punctuation">:</span> New Author
        <span class="token key atrule">titleUpdateForm</span><span class="token punctuation">:</span> Update Author
        <span class="token key atrule">titleCreateForm</span><span class="token punctuation">:</span> Create Author
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./field-nesteditems.html">Контентное поле Nested Items</a></li></ul></div>`,40))])}const f=o(u,[["render",i]]);export{v as __pageData,f as default};
